<script setup lang="ts">
import {ref,computed,watch,nextTick,onUnmounted} from 'vue'
import AuthorField from './AuthorField.vue'
import {ArrowDownRight} from 'lucide-vue-next'
import StateFields from './StateFields.vue'
import {fieldImage} from './field-image'
import type {AuthorValue,CustomField} from './types'
type Value=string|number|boolean|string[]|null
const props=defineProps<{value:AuthorValue}>()
const kind=ref<'playerFields'|'statusFields'>('playerFields'),selected=ref(''),phone=ref(false),playerView=ref(false),answers=ref<Record<string,Value>>({}),notice=ref(''),dragged=ref(''),newType=ref<CustomField['type']>('text')
const fields=computed(()=>props.value[kind.value]),field=computed(()=>fields.value.find(f=>f.id===selected.value)),index=computed(()=>fields.value.findIndex(f=>f.id===selected.value)),limit=computed(()=>kind.value==='playerFields'?12:20)
const types:[CustomField['type'],string][]=[['text','短文字'],['longtext','长文字'],['number','数字'],['select','单选 / 下拉'],['multiselect','多选'],['list','清单'],['boolean','是 / 否'],['image','图片'],['random','随机选项']]
watch(fields,items=>{if(!items.some(f=>f.id===selected.value))selected.value=items[0]?.id||'';for(const f of items)if(!(f.id in answers.value))answers.value[f.id]=f.defaultValue},{immediate:true,deep:true})
watch(()=>fields.value.map(f=>JSON.stringify([f.id,f.type,f.defaultValue,f.options])),()=>{for(const f of fields.value)answers.value[f.id]=f.defaultValue})
const undoStack=ref<string[]>([]),redoStack=ref<string[]>([]);let restoring=false,resizing=false
const snapshot=()=>JSON.stringify({fields:fields.value,formTitle:props.value.formTitle,statusTitle:props.value.statusTitle,statusTheme:props.value.statusTheme})
watch(snapshot,(current,old)=>{if(!restoring&&!resizing&&current!==old){undoStack.value=[...undoStack.value.slice(-19),old];redoStack.value=[]}})
watch(kind,()=>{undoStack.value=[];redoStack.value=[];selected.value=fields.value[0]?.id||''})
async function restore(direction:'undo'|'redo'){const from=direction==='undo'?undoStack:redoStack,to=direction==='undo'?redoStack:undoStack;const raw=from.value.pop();if(!raw)return;to.value.push(snapshot());restoring=true;const v=JSON.parse(raw);props.value[kind.value]=v.fields;props.value.formTitle=v.formTitle;props.value.statusTitle=v.statusTitle;props.value.statusTheme=v.statusTheme;await nextTick();restoring=false;notice.value='已恢复编辑步骤，保存后生效。'}
function identity(){return 'author_field_'+crypto.randomUUID().replaceAll('-','').slice(0,16)}
function defaults(f:CustomField){f.options=['select','multiselect','random'].includes(f.type)?['选项一','选项二']:[];f.defaultValue=f.type==='number'?100:f.type==='boolean'?false:['multiselect','list'].includes(f.type)?[]:['select','random'].includes(f.type)?'选项一':'';f.minimum=null;f.maximum=null;answers.value[f.id]=f.defaultValue}
function add(){if(fields.value.length>=limit.value)return;const f:CustomField={id:identity(),label:'新的字段',type:newType.value,required:false,defaultValue:'',options:[],minimum:null,maximum:null,scope:'player',width:'full',group:'',presentation:'default',minHeight:44};defaults(f);fields.value.push(f);selected.value=f.id;notice.value='已添加字段，点击画布或大纲设置属性。'}
function copy(){if(!field.value||fields.value.length>=limit.value)return;const f=JSON.parse(JSON.stringify(field.value)) as CustomField;f.id=identity();f.label=(f.label+' 副本').slice(0,40);fields.value.splice(index.value+1,0,f);selected.value=f.id;notice.value='字段已复制。'}
function move(direction:number){const from=index.value,to=from+direction;if(from<0||to<0||to>=fields.value.length)return;[fields.value[from],fields.value[to]]=[fields.value[to],fields.value[from]];notice.value='字段已移动到第 '+(to+1)+' 位。'}
function remove(){const at=index.value;if(at<0)return;fields.value.splice(at,1);selected.value=fields.value[Math.min(at,fields.value.length-1)]?.id||'';notice.value='字段已删除，可撤销。保存配置后生效。'}
function optionsChanged(event:Event){if(!field.value)return;const f=field.value;f.options=[...new Set((event.target as HTMLInputElement).value.split(/[,，]/).map(s=>s.trim()).filter(Boolean))].slice(0,20);f.defaultValue=f.type==='multiselect'?(Array.isArray(f.defaultValue)?f.defaultValue.filter(v=>f.options.includes(v)):[]):f.options.includes(String(f.defaultValue))?f.defaultValue:f.options[0]??null}
async function defaultImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0],target=field.value;if(!file||!target)return;try{const data=await fieldImage(file);if(target.type==='image'&&fields.value.some(f=>f.id===target.id)){target.defaultValue=data;notice.value='图片已加入，请保存配置。'}}catch(e){notice.value=(e as Error).message}}
function bound(key:'minimum'|'maximum',event:Event){if(field.value){const v=(event.target as HTMLInputElement).value;field.value[key]=v===''?null:Number(v)}}
function dragStart(id:string,event:DragEvent){dragged.value=id;event.dataTransfer?.setData('text/plain',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function drop(targetId:string,event:DragEvent){if(playerView.value)return;const id=dragged.value,from=fields.value.findIndex(f=>f.id===id),to=fields.value.findIndex(f=>f.id===targetId);dragged.value='';if(from<0||to<0||from===to)return;const rect=(event.currentTarget as HTMLElement).getBoundingClientRect(),ratio=(event.clientX-rect.left)/rect.width;const item=fields.value[from],target=fields.value[to];fields.value.splice(from,1);fields.value.splice(fields.value.indexOf(target)+(event.clientY>rect.top+rect.height/2?1:0),0,item);if(ratio<.2||ratio>.8){item.width='half';target.width='half'}selected.value=id;notice.value='已调整布局；也可用上移、下移及宽度选项完成。'}
let stopResize:(()=>void)|undefined
function resize(event:PointerEvent,item:CustomField){event.preventDefault();event.stopPropagation();stopResize?.();selected.value=item.id;const before=snapshot(),startX=event.clientX,startY=event.clientY,height=item.minHeight||44;resizing=true;const change=(e:PointerEvent)=>{item.minHeight=Math.max(44,Math.min(400,Math.round((height+e.clientY-startY)/8)*8));if(e.clientX-startX>40)item.width='full';else if(e.clientX-startX< -40)item.width='half'};const stop=()=>{window.removeEventListener('pointermove',change);window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',stop);if(snapshot()!==before){undoStack.value=[...undoStack.value.slice(-19),before];redoStack.value=[]}void nextTick(()=>{resizing=false});stopResize=undefined};stopResize=stop;window.addEventListener('pointermove',change);window.addEventListener('pointerup',stop,{once:true});window.addEventListener('pointercancel',stop,{once:true})}
onUnmounted(()=>stopResize?.())
</script>
<template>
<section class="field-designer" aria-label="可视化表单与状态栏编辑器">
 <div class="designer-toolbar"><div class="workspace-pills"><button :aria-pressed="kind==='playerFields'" @click="kind='playerFields'">开局表单</button><button :aria-pressed="kind==='statusFields'" @click="kind='statusFields'">状态栏</button></div><button :aria-pressed="playerView" @click="playerView=!playerView">{{playerView?'返回编辑画布':'玩家视角'}}</button><button :aria-pressed="phone" @click="phone=!phone">{{phone?'切换桌面预览':'切换手机预览'}}</button><button :disabled="!undoStack.length" @click="restore('undo')">撤销</button><button :disabled="!redoStack.length" @click="restore('redo')">重做</button></div>
 <p class="muted">从大纲或画布选择字段。拖动字段标题排序，拖到卡片左右边缘并排；拖动右下角调整高度与整行/半行。也可用属性面板和上移、下移按钮。试填不会写入玩家存档。</p><p v-if="notice" role="status">{{notice}}</p>
 <div class="designer-grid">
 <aside class="designer-outline" aria-label="字段大纲"><h2>字段大纲 <small>{{fields.length}} / {{limit}}</small></h2><ol><li v-for="(item,i) in fields" :key="item.id"><button :aria-label="'大纲选中 '+item.label" :aria-pressed="selected===item.id" :draggable="!playerView" @dragstart="dragStart(item.id,$event)" @dragover.prevent @drop.prevent="drop(item.id,$event)" @click="selected=item.id;playerView=false">{{i+1}} · {{item.label}}<small>{{types.find(t=>t[0]===item.type)?.[1]}}{{item.required?' · 必填':''}}</small></button></li></ol><label>新增字段类型<select v-model="newType" aria-label="新增字段类型"><option v-for="[id,name] in types" :key="id" :value="id">{{name}}</option></select></label><button :disabled="fields.length>=limit" @click="add">添加字段</button></aside>
 <section class="designer-canvas" :class="{phone}" aria-label="实际组件预览"><header><h2>{{kind==='playerFields'?(value.formTitle||'你的开局信息'):(value.statusTitle||'人物状态')}}</h2><small>{{playerView?'玩家视角 · 仅试填':'编辑画布 · 点选字段'}}</small></header><p v-if="!fields.length" class="empty">还没有字段，请从左侧添加。</p>
 <template v-if="playerView&&kind==='statusFields'"><StateFields :fields="fields" :values="Object.fromEntries(fields.map(f=>[f.id,f.defaultValue]))" :theme="value.statusTheme"/></template>
 <div v-else class="canvas-fields"><template v-for="(item,i) in fields" :key="item.id"><h3 v-if="item.group&&item.group!==fields[i-1]?.group" class="canvas-group">{{item.group}}</h3><article class="canvas-field" :class="{selected:!playerView&&selected===item.id,half:item.width==='half'}" :data-field-id="item.id" @click="!playerView&&(selected=item.id)" @focusin="!playerView&&(selected=item.id)" @dragover.prevent @drop.prevent="drop(item.id,$event)"><button v-if="!playerView" class="field-select" :draggable="true" :aria-label="'选中字段 '+item.label" :aria-pressed="selected===item.id" @dragstart="dragStart(item.id,$event)" @dragend="dragged=''">{{i+1}} · {{item.label}}</button><AuthorField v-if="kind==='playerFields'" :field="item" :model-value="item.id in answers?answers[item.id]:item.defaultValue" @update:model-value="answers[item.id]=$event"/><StateFields v-else :fields="fields" :values="{[item.id]:item.defaultValue}" :theme="value.statusTheme"/><button v-if="!playerView" class="resize-handle" :aria-label="'调整 '+item.label+' 的尺寸'" @pointerdown="resize($event,item)" @keydown.left.prevent="item.width='half'" @keydown.right.prevent="item.width='full'" @keydown.up.prevent="item.minHeight=Math.max(44,(item.minHeight||44)-8)" @keydown.down.prevent="item.minHeight=Math.min(400,(item.minHeight||44)+8)"><ArrowDownRight :size="16"/></button></article></template></div>
 </section>
 <aside v-if="!playerView" class="designer-inspector" aria-label="选中字段的属性"><details><summary>面板设置</summary><label v-if="kind==='playerFields'">开局表单标题<input v-model="value.formTitle" maxlength="60"></label><template v-else><label>状态栏标题<input v-model="value.statusTitle" maxlength="60"></label><label>状态栏主题<select aria-label="状态栏主题" v-model="value.statusTheme"><option value="paper">简洁</option><option value="scroll">卷轴</option><option value="terminal">终端</option><option value="soft">柔和</option></select></label></template></details><template v-if="field"><h2>字段属性</h2><label>字段名称<input aria-label="字段名称" v-model="field.label" maxlength="40"></label><label>字段类型<select aria-label="字段类型" v-model="field.type" @change="defaults(field)"><option v-for="[id,name] in types" :key="id" :value="id">{{name}}</option></select></label><label>分组名称<input v-model="field.group" maxlength="40" placeholder="留空不分组"></label><label v-if="field.type==='select'">选择呈现<select aria-label="选择呈现" v-model="field.presentation"><option value="default">默认下拉</option><option value="radio">平铺单选</option><option value="dropdown">下拉选择</option></select></label><label v-if="['select','multiselect','random'].includes(field.type)">可选项（逗号分隔）<input aria-label="可选项（逗号分隔）" :value="field.options.join('，')" @change="optionsChanged"></label>
 <label>初始值<input v-if="field.type==='number'" aria-label="初始值" type="number" v-model.number="field.defaultValue"><select v-else-if="field.type==='boolean'" aria-label="初始值" v-model="field.defaultValue"><option :value="true">是</option><option :value="false">否</option></select><select v-else-if="field.type==='select'||field.type==='random'" aria-label="初始值" v-model="field.defaultValue"><option v-for="option in field.options" :key="option">{{option}}</option></select><input v-else-if="field.type==='image'" aria-label="初始图片" type="file" accept="image/png,image/jpeg,image/webp" @change="defaultImage"><textarea v-else-if="field.type==='multiselect'||field.type==='list'" aria-label="初始值" :value="Array.isArray(field.defaultValue)?field.defaultValue.join('\n'):''" placeholder="每行一项，最多20项" @change="field.defaultValue=($event.target as HTMLTextAreaElement).value.split('\n').map(v=>v.trim()).filter(Boolean)"></textarea><textarea v-else-if="field.type==='longtext'" aria-label="初始值" :value="String(field.defaultValue??'')" @input="field.defaultValue=($event.target as HTMLTextAreaElement).value" maxlength="2000"></textarea><input v-else aria-label="初始值" v-model="field.defaultValue" maxlength="500"></label>
 <div v-if="field.type==='number'"><label>最小值<input aria-label="最小值" type="number" :value="field.minimum??''" @input="bound('minimum',$event)"></label><label>最大值<input aria-label="最大值" type="number" :value="field.maximum??''" @input="bound('maximum',$event)"></label></div><label v-if="kind==='statusFields'">应用对象<select aria-label="应用对象" v-model="field.scope"><option value="player">当前玩家</option><option value="characters">所有人物</option></select></label><label>字段宽度<select aria-label="字段宽度" v-model="field.width"><option value="full">整行</option><option value="half">半行（手机自动整行）</option></select></label><label>最低高度<input type="number" v-model.number="field.minHeight" min="44" max="400"></label><label class="required"><input type="checkbox" v-model="field.required">必填字段</label><div class="designer-actions"><button :disabled="index===0" @click="move(-1)">上移字段</button><button :disabled="index===fields.length-1" @click="move(1)">下移字段</button><button :disabled="fields.length>=limit" @click="copy">复制字段</button><button @click="remove">删除字段</button></div><details><summary>字段标识</summary><small>{{field.id}}</small></details></template><p v-else>选择一个字段开始编辑。</p></aside>
 </div><p class="muted">画布修改随作者配置保存；已开始的玩家存档保持原版本。</p>
</section>
</template>
<style scoped>
.designer-toolbar,.designer-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.designer-grid{display:grid;grid-template-columns:170px minmax(260px,1fr) 235px;gap:16px;align-items:start}.designer-outline,.designer-inspector,.designer-canvas{min-width:0;padding:16px;border:1px solid var(--line,#e8e1d8);border-radius:12px;background:var(--paper,#fffdf9)}.designer-outline h2,.designer-inspector h2,.designer-canvas h2{font-size:17px;margin:0 0 12px}.designer-outline small,.designer-canvas small{display:block;font-size:12px;opacity:.8}.designer-outline ol{list-style:none;padding:0}.designer-outline li{margin:6px 0}.designer-outline li button{width:100%;text-align:left}.designer-outline [aria-pressed=true]{border-color:var(--accent,#b56229);background:var(--accent-soft,#b5622910)}.designer-inspector label,.designer-outline label{display:block;margin:14px 0}.field-designer input:not([type=checkbox]),.field-designer select,.field-designer textarea{width:100%;max-width:100%;min-height:44px}.field-designer button,.field-designer summary{min-height:44px}.designer-canvas.phone{max-width:390px;width:100%;margin:auto}.canvas-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.canvas-field{position:relative;grid-column:span 2;min-width:0;border:1px solid transparent;border-radius:10px;padding:12px 12px 36px}.canvas-field.half{grid-column:span 1}.canvas-field.selected{border-color:var(--accent,#b56229);background:#b5622908}.field-select{font-size:12px;cursor:grab;text-align:left}.canvas-group{grid-column:span 2;font-size:15px}.resize-handle{position:absolute;right:0;bottom:0;cursor:nwse-resize;touch-action:none;font-size:18px;width:44px}.designer-inspector .required{display:flex;gap:8px;align-items:center}.required input{width:18px;height:18px}.designer-inspector details{margin-top:16px}.designer-inspector small{overflow-wrap:anywhere}.designer-canvas.phone .canvas-field{grid-column:span 2}@media(max-width:1150px){.designer-grid{grid-template-columns:150px minmax(240px,1fr)}.designer-inspector{grid-column:span 2}}@media(max-width:700px){.designer-grid{grid-template-columns:minmax(0,1fr)}.designer-inspector{grid-column:span 1}.designer-outline ol{max-height:200px;overflow:auto}}
</style>
